#include <iostream>
using namespace std;

int main() {
    int fish = 0;
    int next = 0;
    cin >> fish >> next;

    int& other = fish;
    other = next;

    cout << "原名儿是 " << fish << endl;
    cout << "新名儿是 " << other << endl;
    return 0;
}
